<?php
require_once __DIR__.'/../includes/admin.php';require_role(['super_admin','admin','editor']);$pdo=db();if(is_post()){verify_csrf();$a=$_POST['action']??'';try{if($a==='status'){$id=(int)$_POST['id'];$pdo->prepare('UPDATE contact_messages SET status=? WHERE id=?')->execute([$_POST['status']??'new',$id]);log_admin("Updated message #$id");flash('admin_success','Message status updated.');}if($a==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM contact_messages WHERE id=?')->execute([$id]);log_admin("Deleted message #$id");flash('admin_success','Message deleted.');}}catch(Throwable $e){flash('admin_error','Message error: '.$e->getMessage());}redirect('admin/messages.php');}$rows=$pdo->query('SELECT * FROM contact_messages ORDER BY created_at DESC')->fetchAll();admin_page('Messages','messages','Read and manage messages submitted through the contact form.');admin_flash();?><div class="admin-panel"><h2>Contact Inbox</h2><div class="admin-table-wrap"><table class="admin-table"><tr><th>Name</th><th>Email</th><th>Subject</th><th>Message</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name']?:'Anonymous')?></td><td><?=e($r['email']?:'—')?></td><td><?=e($r['subject']?:'—')?></td><td style="max-width:330px"><?=e($r['message'])?></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><form method="post" style="display:flex;gap:5px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>new</option><option>read</option><option>archived</option></select><button class="btn small outline">Save</button></form><form method="post" onsubmit="return confirm('Delete message?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small" style="background:var(--red);color:#fff">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php admin_end(); ?>
